INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.NMR', 79, 'Nuclear Magnetic Resonance Analysis', 'Analyzed', 'A nuclear magnetic resonance analysis file contains processed spectra or peak lists derived from raw NMR data. It represents interpreted molecular structure or dynamics data used in chemical or biological characterization. Each file may summarize multiple spectral acquisitions into one analyzed dataset.\nTypical file types: .csv, .txt, .jdx', 'NMR analysis, nuclear magnetic resonance analysis, NMR spectroscopy analysis, metabolomics NMR, chemical structure analysis, peak list analysis, spectral assignment, A.NMR, 1H NMR analysis, 13C NMR analysis, proton NMR analysis, NMR peak integration, MestReNova, 2D NMR analysis', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent, Checksum_PrimaryData', 'Protocol, Type', 'SampleCreationDate, Publish_uri, Standard, Checksum_PrimaryType, DOI, PMID', 'D.NMR', NULL, 'Nuclear Magnetic Resonance Spectroscopy Analysis', NULL, NULL, NULL);
