um": "A.SCXP::Checksum_PrimaryData"}}', NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.SPC', 81, 'Spectroscopy Analysis', 'Analyzed', 'A spectroscopy analysis file contains processed spectral data derived from optical or electromagnetic measurements. It represents interpreted wavelength or intensity data used to characterize material or molecular properties. Each file may summarize multiple spectral readings into one analyzed dataset.\nTypical file types: .csv, .xlsx, .txt', 'spectroscopy analysis, optical spectroscopy analysis, UV-Vis analysis, absorption spectroscopy, fluorescence spectroscopy analysis, Raman analysis, infrared spectroscopy analysis, A.SPC, FTIR analysis, UV/Vis analysis, Raman spectroscopy analysis, spectral peak fitting', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent, Checksum_PrimaryData', 'Protocol, Type, Software', 'SampleCreationDate, Checksum_PrimaryType, Publish_uri, File_SecondaryData, Link_SecondaryData, Checksum_SecondaryData, Checksum_SecondaryType, File_TertiaryData, Link_TertiaryData, Checksum_TertiaryData, Checksum_TertiaryType, DOI, PMID', 'D.SPC', 'MDL', 'Spectroscopy Analysis, Mass Spectrometry Analysis', 'Computational Modeling', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.SPTX', 111, 'Analyzed Spatial Transcriptomics Data', 'Analyzed', 'An analyzed spatial transcriptomics file contains processed gene expression and spatial coordinate data derived from tissue imaging experiments. It represents integrated molecular and positional information used for spatially resolved analyses. Each file may represent one tissue section or a combined dataset across multiple regions.\nTypical file types: .h5ad, .csv, .tsv', 'spatial transcriptomics analysis, spatial gene expression, Visium analysis, slide-seq analysis, spatially resolved transcriptomics, tissue mapping, in situ transcriptomics, A.SPTX, spatial transcriptomics, Space Ranger, Xenium analysis, MERFISH analysis, CosMx analysis, Visium HD analysis, spatial RNA-seq', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent', 'Protocol, Software, Link_Genome, Link_QC, Link_MASKFile', 'Name, SampleCreationDate, Notes, DOI, PMID', 'D.SEQ, D.IMG, TIS', NULL, 'Spatial Transcriptomics', NULL, '{"GEO": {"processed data file": "A.SPTX::File_PrimaryData", "data processing step": "A.SPTX::Software", "genome build/assembly": "A.SPTX::Link_Genome"}}', NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.TITR', 99, 'Titer Assay Analysis', 'Analyzed', 'A titer assay analysis file contains processed results from antibody or viral titer experiments. It represents calculated concentrations or endpoint dilutions used to quantify immune response or viral load. Each file typically summarizes data from serial dilution experiments.\nTypical file types: .csv, .xlsx', 'titer analysis, antibody titer analysis, neutralization titer, endpoint dilution analysis, serology analysis, PRNT analysis, plaque reduction neutralization, IC50 serology, A.TITR, titre analysis, antibody titre analysis, IgG titer analysis, NT50, EC50 titer, area under the curve titer', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent, Checksum_PrimaryData', 'Protocol', 'SampleCreationDate, Checksum_PrimaryType, Publish_uri, Notes, Name, DOI, PMID', 'D.TITR', NULL, 'Antibody Titer Assay Analysis', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.VCF', 142, 'Variant Call Analysis', 'Analyzed', 'A variant call analysis file contains processed genomic variant calls derived from aligned sequencing reads. It represents annotated single nucleotide polymorphisms, insertions, deletions, or structural variants identified against a reference genome. Each file typically corresponds to one sample or a merged cohort dataset.\nTypical file types: .vcf, .vcf.gz, .bcf', 'VCF analysis, variant call format, variant calling analysis, SNP analysis, SNV analysis, indel analysis, genomic variant annotation, GATK output, mutation calling, variant filtering, A.VCF, VCF file, Mutect2, DeepVariant, bcftools', 'UID, File_PrimaryData, Link_PrimaryData, Checksum_PrimaryData, Scientist, Parent', 'Protocol, Software, Type, ReferenceGenome, Pipeline, PipelineVersion, FilterMethod, FilterSet, Repository', 'Link_ReferenceGenome, Accession, RepositoryLink, Publish_uri, Notes, VariantCaller, VariantCallerVersion, AnnotationTool, AnnotationToolVersion, AnnotationReference, Link_AnnotationReference, Link_Pipeline, DOI, PMID', 'A.ALN', NULL, 'Variant Call Filtering', NULL, '{"EVA": {"Analysis/Analysis Alias": "A.VCF::UID", "Analysis/Description": "A.VCF::Notes", "Analysis/Reference": ["A.VCF::ReferenceGenome", "A.VCF::Link_ReferenceGenome"], "Analysis/Software": ["A.VCF::VariantCaller", "A.VCF::Software"], "Analysis/Pipeline Description": "A.VCF::Pipeline", "Files/Analysis Alias": "A.VCF::UID", "Files/File Name": "A.VCF::File_PrimaryData", "Files/MD5": "A.VCF::Checksum_PrimaryData", "Project/Publication(s)": "A.VCF::PMID"}}', NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.VLT', 149, 'Voltammetry Analysis', 'Analyzed', 'A voltammetry analysis file holds blank-subtracted voltammograms and derived redox descriptors, including digital-simulation fits (for example DigiElch) to the measured current-potential data.', 'voltammetry analysis, redox descriptors, blank-subtracted voltammogram, DigiElch fit, electrochemical analysis, A.VLT, cyclic voltammetry analysis, square-wave voltammetry analysis, redox potential analysis, peak current analysis, digital simulation fit, half-wave potential', 'UID, File_PrimaryData, Link_PrimaryData, Checksum_PrimaryData, Parent, Scientist', 'Protocol, Type, Software, Method', 'Checksum_PrimaryType, File_SecondaryData, Link_SecondaryData, Checksum_SecondaryData, Checksum_SecondaryType, SampleCreationDate, Publish_uri, Notes, DOI, PMID', 'D.VLT', NULL, 'Voltammetry Analysis', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('A.WBLT', 141, 'Western Blot Analysis', 'Analyzed', 'A western blot analysis file contains processed band intensity or densitometry measurements derived from western blot image data. It represents quantified protein expression levels normalized against loading controls and compared across experimental lanes. Each file typically summarizes one gel or a set of blot images.\nTypical file types: .csv, .xlsx, .tiff', 'western blot analysis, immunoblot analysis, protein gel analysis, densitometry analysis, WB analysis, protein expression analysis, band quantification, western blot results, A.WBLT, western blotting analysis, band densitometry, ImageJ densitometry, Image Studio analysis, loading control normalization', 'UID, File_PrimaryData, Link_PrimaryData, Checksum_PrimaryData, Scientist, Parent', 'Lab, SampleCreationDate, Protocol', 'ModelName, ModelType, ModelDescription, Domain, Resolution, SourceCode, Docker, Notes, Checksum_PrimaryType, File_SecondaryData, Link_SecondaryData, Checksum_SecondaryData, Checksum_SecondaryType, DOI, PMID', 'D.WBLT', NULL, 'Western Blot Analysis', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('AB', 68, 'Antibody', 'Source', 'An antibody sample contains purified immune proteins that specifically recognize and bind to target molecules. These samples are used in experimental procedures that detect, label, or isolate biological components. Each antibody is defined by its binding specificity, source, and production method.', 'antibody, immunoglobulin, Ab, mAb, monoclonal antibody, polyclonal antibody, primary antibody, secondary antibody, IgG, IgM, IgA, IgE, detection antibody, blocking antibody, isotype control', 'UID, Name', 'Catalog#, Vendor, Analyte, Fluorophore, CatalogLink, Panel', 'Clone, Reporter, Lot#, RRID, Publish_uri, Notes, AminoAcidMutations, Description, Protocol, Barcode, ExperimentType, Channel, Isotype, Concentration, SecondaryAntibody, SecondaryAntibodyLink, Dilution, DOI, PMID', NULL, 'ABP, PAV, MUS, CEL, D.FLOW, D.BSRA, D.IMG, D.ELSA, D.FCS, D.ADCD, D.ADCP, D.ADNP, D.ADNKA, D.GLYN, D.CYTOF', NULL, 'Pathogen Challenge and Antibody Depletion, Flow Cytometry, Immunohistochemistry, ELISA, Bacterial Survivability Restriction Assay, Imaging, Antibody-Dependent Functional Profiling (ADFP), Device Imaging, CyTOF, Cyclic Immunofluorescence (CyCIF), Glycosylation Assay, Tissue Imaging, Multiplex Bead-Based Antibody Titer Panel Assay, Antibody-Dependent Cellular Phagocytosis (ADCP), Antibody-Dependent Complement Deposition (ADCD) Assay, Antibody-Dependent NK Cell Activation Assay, Antibody-Dependent Neutrophil Phagocytosis (ADNP)', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('ABP', 72, 'Antibody Panel Sample (Collection of Antibodies)', 'Source', 'An antibody panel sample represents a curated collection of antibodies used for detection or labeling in assays. It defines the set of reagents applied to measure or visualize specific proteins, cells, or molecular targets. This sample type groups several antibodies (AB) under a single UID.', 'antibody panel, antibody cocktail, staining panel, flow panel, CyTOF panel, multiplex antibody panel, antibody collection, antibody set, reagent panel, ABP, flow cytometry panel, mass cytometry panel, multicolor flow panel, fluorochrome panel, antibody mix', 'UID, Name, Scientist, Parent', 'Protocol', 'SampleCreationDate, Publish_uri, DateRange, Notes, LinkCohortFile, DOI, PMID', 'AB', 'D.FLOW, D.FCS, DNA, D.CYTOF, D.IMG, D.ELSA, D.FCRB', 'Flow Cytometry, CyTOF, Cyclic Immunofluorescence (CyCIF), ELISA, Multiplex Bead-Based Antibody Titer Panel Assay, Tissue Imaging', 'Flow Cytometry, Library Creation, CyTOF, Cyclic Immunofluorescence (CyCIF), ELISA', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('BAC', 23, 'Bacteria Sample', 'Source', 'A bacteria sample represents a microbial strain used in an experiment, either as an infectious agent or as material isolated from another biological source. It serves as a basis for studying host interactions, gene expression, or microbial composition.', 'bacteria, bacterial strain, microbial sample, pathogen, Mycobacterium tuberculosis, MTB, E. coli, bacterial culture, microbe, infectious agent, microbial isolate, BAC, bacterium, H37Rv, M. tuberculosis', 'UID, Name, Scientist', 'Protocol, Species, Parent, StorageType, Genotype, TaxonomyID, Source', 'SampleCreationDate, StorageSite, StorageLocation, Substrain, SubstrainReference, Phenotype, Morphology, Culture, InoculumPrep, ODFrozen, ODWavelength, Notes, Publish_uri, Strain, GramStaining, Barcode, Qtag, Lab, Link_Sequence, DOI, PMID', 'TIS', 'DNA, MUS, PAV, CEL, D.ADCD, D.ADCP, D.ADNP, D.BSRA, RNA', 'Bacterial Extraction, DNA Extraction', 'Pathogen Challenge and Antibody Depletion, DNA Extraction, Cell Culture, Bacterial Survivability Restriction Assay', NULL, NULL);
