INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('M.CNN', 112, 'Convolutional Neural Network Model', 'Analyzed', 'A convolutional neural network (CNN) model file contains trained parameters or outputs from deep learning models used for image or pattern recognition. It represents computationally derived predictions or classifications rather than direct experimental measurements. Each file typically summarizes training results from many input images.\nTypical file types: .h5, .pt, .onnx', 'convolutional neural network, CNN, deep learning model, image classification model, neural network, computer vision model, machine learning model, .h5 model, .pt model, torch model, M.CNN, PyTorch model, U-Net, ResNet, ONNX model', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent', 'Protocol, Model_Type', 'Type, Publish_uri, DOI, PMID', 'D.IMG', NULL, 'Convolutional Neural Network (CNN) Assay', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('M.LMM', 101, 'Linear Mixed Model', 'Analyzed', 'A linear mixed model file contains statistical outputs from models that include both fixed and random effects. It represents results used to analyze complex datasets with repeated measures or hierarchical structure. Each file typically summarizes modeled results from multiple input datasets.\nTypical file types: .rds, .csv, .txt', 'linear mixed model, LMM, mixed effects model, REML, random effects model, longitudinal model, repeated measures model, statistical model, fixed effects, M.LMM, linear mixed-effects model, lme4, lmer, mixed model, hierarchical linear model', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent, Checksum_PrimaryData', 'Protocol, TrainingDatasets, ValidationDatasets', 'Name, SampleCreationDate, Checksum_PrimaryType, Type, Publish_uri, DOI, PMID', 'D.TITR, D.FCRB, D.ADCP, D.ADNP, A.MSP', NULL, 'Linear Mixed Model', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('MDL', 118, 'Model', 'Analyzed', 'A model file represents a model definition or machine learning output used for predictive analysis. It contains parameters, trained weights, or configuration metadata describing a computational model. Each file typically summarizes results from training on multiple datasets.\nTypical file types: .mdl, .json, .h5', 'model, computational model, predictive model, machine learning model, AI model, trained model, statistical model, data model, model output, trained weights, MDL, mathematical model, computational modeling, predictive modeling', 'UID, File_PrimaryData, Link_PrimaryData, Scientist, Parent, Checksum_PrimaryData', 'Protocol, Type, Description, Repository, RepositoryLink, TrainingDatasets, ValidationDatasets', 'AdditionalData, AdditionalData_Link, Notes, Checksum_PrimaryType, DOI, PMID', 'A.SPC, D.WTR', NULL, 'Model Validation, Computational Modeling, TransCompR Cross-Species Computational Modeling', NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('MUS', 10, 'Mouse', 'Source', 'A mouse sample represents an experimental animal used as a model system. Mice may be exposed to specific treatments or conditions, and tissues or cells are collected from them for downstream analysis.', 'mouse, Mus musculus, murine, animal model, rodent, C57BL/6, BALB/c, transgenic mouse, knockout mouse, experimental mouse, lab mouse, MUS, mice, house mouse, mouse model, collaborative cross, CC', 'UID, Name, Scientist', 'Sex, DateOfBirth, Strain, Genotype, SourceFacility, Study, Cohort, Classification, SacrificeDate, Treatment1, Disease, SurvivalTime, Vendor, Protocol', 'Link_StrainReference, Phenotype, StorageType, StorageLocation, StorageSite, Source, ParentM, ParentF, Notes, Treatment1Type, Treatment1Date, Treatment1Parent, Treatment1Route, Treatment1Dose, Treatment1DoseUnits, Treatment1Reference, Treatment1Time, Treatment1TimeUnits, Protocol_Treatment1, Treatment2Type, Treatment2, Treatment2Date, Treatment2Parent, Treatment2Route, Treatment2Dose, Treatment2DoseUnits, Treatment2Reference, Treatment2Time, Treatment2TimeUnits, Protocol_Treatment2, Treatment3Type, Treatment3, Treatment3Date, Treatment3Route, Treatment3Dose, Treatment3DoseUnits, DiseaseStage, DiseaseReference, Publish_uri, Treatment3Parent, AlternativeIDs, SacrificeDescription, MortalityObservation, Treatment1DoseRule, Treatment2DoseRule, Treatment3DoseRule, Group_InCohort, Provider, ProviderProduct#, CountryOfOrigin, Treatment4, Treatment4Type, Treatment4Date, Treatment4Parent, Treatment4Route, Treatment4Dose, Treatment4DoseUnits, Link_BodyWeight, Parent, DOI, PMID', 'AB, BAC, CHM, CEL, VIR', 'TIS, CEL, PAV', 'Pathogen Challenge and Antibody Depletion, Chemical Challenge, Patient-Derived Xenograft (PDX) Cell Line Generation', 'Tissue Collection, Cell Isolation, Cell Line Creation, Intravital Microscopy', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('NHP', 41, 'Non Human Primate', 'Source', 'A non-human primate sample originates from an organism closely related to humans within the primate order. These samples are collected to study biological processes that share genetic and physiological similarities with human systems. Each reflects controlled collection and handling specific to the species and study design.', 'NHP, non-human primate, macaque, rhesus macaque, cynomolgus, primate model, Macaca mulatta, Macaca fascicularis, African green monkey, marmoset, nonhuman primate, monkey, rhesus monkey, cynomolgus macaque, crab-eating macaque', 'UID, Name, Scientist', 'Sex, Species, Origin, DateOfBirth, Arm, Study, Funder, StudyDesign, DataDictionary', 'ID, Facility, Notes, Contact, Publish_uri, CoScientist, Treatment1, Treatment1Type, Treatment1Route, Treatment1Date, Treatment1Dose, Treatment1DoseUnits, Treatment2, Treatment2Type, Treatment2Route, Treatment2Date, Treatment2Dose, Treatment2DoseUnits, NecropsyDate, Supplier, Treatment3, Treatment3Type, Protocol, TotalCFU, LungCFU, LymphNodeCFU, TotalPathologyScore, LungPathologyScore, LymphNodePathologyScore, CFUUnits, AlternativeID, Link_StudyDesign, NewGranulomaCount, MTB_Cohort, BCG_Cohort, DOI, PMID', NULL, 'PAV, CEX, A.FLOW, CEL', NULL, 'Patient Visit, Tissue Collection, Flow Cytometry Analysis', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('OOC', 74, 'Organ on Chip', 'Processed', 'An organ-on-chip sample consists of living cells arranged within a microengineered device that mimics the structure and function of human tissues. These samples recreate physiological conditions at a miniature scale, allowing controlled investigation of organ-level responses. Each represents a unique combination of cell types, architecture, and flow conditions.', 'organ on chip, microphysiological system, MPS, microfluidic device, gut on chip, lung on chip, liver on chip, in vitro organ model, tissue chip, body on chip, microfluidic organ, OOC, organ-on-a-chip, organ chip, vascularized chip', 'UID, Name, Scientist, Parent', 'Type, Protocol, Media, Stimulation, Treatment1, SeedingDate, PerfusingDate, ExperimentType, Link_Design, Material, Protocol_Device', 'SampleCreationDate, Publish_uri, Vascularization, Treatment1Dose, Treatment1DoseUnits, Treatment1Reference, Treatment1Protocol, DOI, PMID', 'CEL', 'D.IMG, CEX, RNA', 'Organ-on-a-Chip Device Fabrication', 'Cell Extraction, RNA Extraction, Device Imaging, Computational Modeling', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('PAT', 25, 'Patient', 'Source', 'A patient sample represents a human participant enrolled in a study. It serves as the source for clinical information and biological material collected to investigate health, disease, or treatment effects.', 'patient, human subject, study participant, clinical participant, donor, volunteer, human donor, study cohort member, enrolled subject, clinical trial participant, PAT, Homo sapiens, human participant, clinical subject', 'UID, Name, Scientist', 'ID, Age, Sex, Notes, Arm, StudyDesign, Disease, Study, Protocol, DataDictionary', 'Household, Age_Units, StatusHIV, Classification, Contact, Reference, StatusBCGVaccination, Ethnicity, Race, SubjectLocation, Arm_Group_Name, Arm_Collapsed_Grouping, DiseaseReference, DiseaseStage, Publish_uri, Scarring, Height, Height_Units, Weight, Weight_Units, BMI, TB_History, RecruitDate, EnrollmentDate, RecruitReason, Treatment_Outcome, Phenotype, Alcohol, Smoke, SmokeDuration_Units, SmokeDuration, DiagnosisDate, VaccinationHistory, COVIDHistory, TravelHistory, BaselineCohort, MenstrualStage, QFT_Result, QFT_Value, MGITCulture_Result, Funder, Relationship, DiseaseHistory, Substance_Use, Cannabis_Use, Waterpipe_Use, Methamphetamine_Use, Methaqualone_Use, Polysubstances_Use, Smear_Result, StatusCOVID, TST_Result, TimeToTB, TimeToTBUnits, Symptoms, ClassificationCohort, Deceased, KPS_Score, Tumor_Grade, Tumor_IDH, MGMT_Promoter_Status, Initial_Diagnosis, Parent, TimeSinceCOVID, Gestation, DeliveryMode, BirthWeight, BirthWeightUnits, PerinatalHealth, TimeSinceBCGVax, CardiacIllness, Allergy, ChronicRespiratoryDisease, ActiveCOVID19, Pregnant, Previous_COVID19, COVID19Vax, COVID