eXPert_Ultra_Ranking, GeneXPert_Ultra_Rif_Resistance, MTB_LiquidCulture_Result, MTB_LiquidCulture_Speciation, MTB_SputumSmear_Result, MTB_SputumSmear_Score, Chest_XRAY_Reading, MGIT_Culture_Result, Blood_Agar_Result, HIV_Test_Result, HIV_Test_Type, COVID19_Test_Result, COVID19_Test_Type, QFN_Data, Visible_Lesions_PETCT, VisibleLesion1_PETCT_ActiveTB, VisibleLesion1_PETCT_Location, VisibleLesion1_PETCT_FDG, VisibleLesion1_Total_Glycolytic_Activity, VisibleLesion2_PETCT_ActiveTB, VisibleLesion2_PETCT_Location, VisibleLesion2_PETCT_FDG, VisibleLesion2_Total_Glycolytic_Activity, VisibleLesion3_PETCT_ActiveTB, VisibleLesion3_PETCT_Location, VisibleLesion3_PETCT_FDG, VisibleLesion3_Total_Glycolytic_Activity, VisibleLesion4_PETCT_ActiveTB, VisibleLesion4_PETCT_Location, VisibleLesion4_PETCT_FDG, VisibleLesion4_Total_Glycolytic_Activity, DOI, PMID', 'NHP, PAT, BAC, AB, MUS', 'TIS, D.IMG, CEX, CEL', 'Patient Visit, Pathogen Challenge and Antibody Depletion, Tissue Collection', 'Tissue Collection, PET/CT Scan, Patient Visit, Magnetic Resonance Imaging (MRI)', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('RNA', 60, 'RNA Sample', 'Processed', 'An RNA sample contains extracted ribonucleic acid from cells or tissues. It is used to study gene expression, transcriptional profiles, or other RNA-based molecular processes.', 'RNA, ribonucleic acid, extracted RNA, mRNA, total RNA, messenger RNA, RNA isolation, transcriptome input, RNA extraction, gene expression input, RNA sample, microRNA, small RNA, poly(A) RNA, RNA extract', 'UID, Name, Scientist, Parent', 'Protocol, Type, Volume, Concentration, RIN, Genes, ExtractionMethod, Link_QC', 'SampleCreationDate, Lab, VolumeUnits, ConcUnits, Publish_uri, QC_Instrument, Notes, StorageType, Titer, DOI, PMID', 'TIS, CEL, BAC, OOC', 'DNA, D.PCR', 'RNA Extraction', 'Library Creation, cDNA Synthesis, Polymerase Chain Reaction (PCR)', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('SLD', 110, 'Slide/Tissue Section', 'Processed', 'A slide of tissue section represents a mounted and prepared sample containing thin slices of biological tissue. It is used for spatial transcriptomics or imaging-based assays that map gene expression across tissue architecture.', 'slide, tissue slide, histology slide, microscopy slide, tissue section, FFPE slide, frozen section, stained slide, pathology slide, glass slide, tissue mount, SLD, H&E slide, cryosection, MALDI slide', 'UID, Name, Scientist, Parent', 'Protocol, Type, Assay, Section#, Vial#, RegionType, Volume, BCAValue, ProteinAmount, Timepoint', 'Stain, SampleCreationDate, VolumeUnits, Concentration, ConcentrationUnits, DOI, PMID', 'TIS', 'D.IMG, D.MSP, D.MSI', 'Tissue Sectioning', 'Tissue Imaging, Mass Spectrometry Proteomics, Tissue Sectioning', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('SNSR', 127, 'Sensor Sample', 'Processed', 'A sensor sample represents a physical measurement device or detector used within an experiment. It defines the source of recorded data, linking the collected measurements to a specific instrument, configuration, or deployment.', 'sensor, biosensor, measurement device, detector, electrochemical sensor, optical sensor, monitoring device, probe, transducer, physical sensor, lab sensor, SNSR, gas sensor, sensor fabrication', 'UID, Name, Scientist, Parent', 'Protocol, Type, SimulationData', 'Lab, Publish_uri, DOI, PMID', NULL, 'D.SNSR', 'Sensor Creation', 'Atomic Force Microscopy (AFM), Electrochemical Sensor Assay', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('SUB', 140, 'PubChem Substance', 'Processed', 'A PubChem substance record represents a chemical compound or biological molecule standardized and referenced via the NCBI PubChem database. It serves as a curated chemical entity linked to experimental workflows where specific compounds function as treatments, analytes, or reagents. Each record corresponds to a unique PubChem Compound ID (CID) or Substance ID (SID).', 'substance, PubChem substance, chemical entity, chemical reference, compound, CID, SID, PubChem CID, small molecule, chemical database entry, NCBI compound, reference compound, SUB, PubChem, PubChem SID', 'UID, Name, Scientist', 'Vendor, Manufacturer, Form, Concentration, ConcUnits, Volume, VolumeUnits, Protocol', 'Parent, ProductNumber, Catalog#, Lot#, StorageTempMin, StorageTempMax, StorageTempUnits, Temperature, TemperatureUnits, CrystalSystem, CrystalSize, SpaceGroup, SampleCreationDate, Lab, publish_uri, Notes, DOI, PMID', NULL, 'CHM', NULL, NULL, NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('TIS', 26, 'Tissue Sample', 'Processed', 'A tissue sample represents a portion of biological material collected from an organism. It serves as the source for downstream molecular, cellular, or histological analyses. It also covers fluid specimens such as blood, peripheral blood mononuclear cells (PBMC) and bronchoalveolar lavage (BAL).', 'tissue, biopsy, tissue biopsy, organ sample, biological tissue, excised tissue, FFPE, fresh frozen tissue, tumor tissue, lung tissue, blood, PBMC, BAL, bronchoalveolar lavage, tissue specimen, TIS', 'UID, Name, Scientist, Parent', 'Type, Organ, OrganDetail, StorageType, StorageLocation, ShipDate, ReceiptDate, Treatment, CFU, CFUUnits, BioSampleAccession, CellTypes, Stimulation, Protocol', 'SampleCreationDate, CollectionTime, CollectionTimeUnits, Mass, MassUnits, StorageSite, BALCollectedVolume, BALCollectedVolumeUnits, BALInstilledVolume, BALInstilledVolumeUnits, Volume, VolumeUnits, CellCount, Notes, StudyID, SampleCollectionDate, Contact, Publish_uri, Color, Concentration, ConcentrationUnits, TimeToFreezer, TimeUnits, ViableCellCount, NumVials, TreatmentType, TreatmentDate, TreatmentDose, TreatmentDoseUnits, TreatmentTime, TreatmentTimeUnits, CEQ, CEQUnits, CFU/CEQ, CFU/CEQUnits, TimeOfDetection, Protocol2, Protocol3, Catalog#, ArrayNumber, StorageDate, ReceiptNotes, ShipOrigin, ShippingTemperatures_Origin, ShipID, VialID, Viability%, ConcentrationPerVial, ShipDestination, ShippingTemperatures_Destination, ShipNotes, SurgeryTimepoint, TumorFractionFromCNV, AssociatedCNV, ExtractionInterval, Assay, TumorWeight, TumorWeightUnits, Treatment2, Treatment2Type, Treatment2Dose, Treatment2DoseUnits, Core, Location, ExtractionIntervalNotes, RelevantTimepoint, Part, WeeksSincePrimaryIntervention, Stains, CFU_FileName, CFU_FileLink, Link_OrganWeight, DOI, PMID', 'PAV, MUS', 'DNA, RNA, BAC, D.TITR, D.PEX, D.FCRB, D.ADCD, D.ADCP, D.ADNKA, D.ADNP, D.ADMP, D.ADDCP, D.IMG, D.FLOW, D.CYTOF, CEL, D.BSRA, D.MSP, A.SPTX, SLD, D.WBLT, D.LMX, CEX, D.GPT, D.ELSA, D.LUM, D.MSI', 'Tissue Collection, Patient Visit', 'Mass Spectrometry Proteomics, RNA Extraction, Bacterial Extraction, Titer Assay, Fc Receptor Binding Assay, Antibody-Dependent Functional Profiling (ADFP), Proximity Extension Assay (PEA), Immunohistochemistry, Histopathology, Imaging, Tissue Imaging, Tissue Sectioning, Flow Cytometry, CyTOF, CometChip Assay, Cell Isolation, Bacterial Survivability Restriction Assay, Spatial Transcriptomics, DNA Extraction, Spatial Proteomics, Western Blot, Cell Culture and Organoid Generation, Spatial Metabolomics, Luminex Multiplex Immunoassay, Protein Extraction, GPT Assay, ELISA, Patient-Derived Xenograft (PDX) Cell Line Generation, Antibody-Dependent Cellular Phagocytosis (ADCP), Antibody-Dependent Complement Deposition (ADCD) Assay, Antibody-Dependent NK Cell Activation Assay, Antibody-Dependent Neutrophil Phagocytosis (ADNP), Cell Extraction, Cell Line Creation, Cell Sorting, Cyclic Immunofluorescence (CyCIF), Fourier Transform Infrared Spectroscopy (FTIR), Immunopeptidomics, MALDI Mass Spectrometry Imaging (MALDI-MSI), Organ-on-a-Chip Device Fabrication', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('VIR', 137, 'Virus Sample Type', 'Source', 'A virus sample represents a viral strain or preparation used in an experiment. It may be employed as an infectious agent, a vector, or material isolated from a host for further molecular analysis.', 'virus, viral strain, viral sample, pathogen, SARS-CoV-2, influenza, viral preparation, virus stock, viral vector, live virus, attenuated virus, recombinant virus, viral isolate, VIR, lentivirus', 'UID, Name, Scientist', 'Type, Strain, Species, TaxonomyID, Source_Vendor, GenomeSequence', 'Lot#, Product#, DOI, PMID', NULL, 'MUS, CEL', NULL, 'Pathogen Challenge and Antibody Depletion', NULL, NULL);
INSERT INTO `sample_types_context` (`sample_type`, `sampletype_id`, `name`, `clade`, `description`, `Tags`, `required_metadata`, `standard_metadata`, `possible_metadata_fields`, `parent_sampletypes`, `child_sampletypes`, `associated_assay_parents`, `associated_assay_children`, `repository_attributes`, `sampletype_file_link`) VALUES ('WTR', 143, 'Water Sample', 'Source', 'A water sample is water collected from a source, treatment plant, distribution system or tap for chemical, physical or microbiological water-quality analysis. It can also be the treated output of an electrochemical filtration run, so a water sample may derive from another water sample and a filter device.', 'water sample, water, drinking water, tap water, source water, treated water, environmental water, groundwater, surface water, DWTP, water treatment plant, Superfund, SRP, WTR', 'UID, Name, Scientist', 'Protocol, CollectionDate, Type, Parent, CollectionTime, Region, SourceTap, TreatmentType', 'SampleCreationDate, Reference, DWTP, FlushDurationMinutes, FieldStabilizationMet, Replicate, FieldBlank, BottleType, VolumeCollectedL, Dechlorinated, DechlorinationAgent, DechlorinationDoseMgPerL, RecoveryStandard, RecoveryStandardConcNgPerL, RecoveryStandardAddedWithinHours, StorageTempC, StoredOnIceInField, ExtractionWindowDaysMax, Notes, Lab, Treatment1, Treatment1Type, Treatment1Date, Treatment1Parent, Treatment1Dose, Treatment1DoseUnits, Treatment1Time, Treatment1TimeUnits, Treatment2, Treatment2Type, Treatment2Date, Treatment2Parent, Treatment2Dose, Treatment2DoseUnits, Treatment2Time, Treatment2TimeUnits, DOI, PMID', 'FLT, WTR, CHM, LOC', 'WTR, D.SPC, CHM, D.MSP, D.WTR, D.ICM', 'Electrochemical Filtration, Chemical Challenge, Environmental sample collection', 'Electrochemical Filtration, Spectroscopy, Solid Phase Extraction (SPE), Mass Spectrometry, Water Quality Detection, Ion Chromatography', NULL, NULL);
